     msgs: [{from: "user", to: "res", label: "A? portal.bank.example", kind: "normal"}, {from: "res", to: "auth", label: "A? portal.bank.example", kind: "normal"}, {from: "auth", to: "res", label: "198.51.100.80 (TTL 3600)", kind: "normal"}, {from: "res", to: "user", label: "198.51.100.80", kind: "normal"}],
     facts: [["Real IP", "198.51.100.80"], ["Cached for", "1 hour"], ["Resolver", "Also answers the internet (misconfigured)"]],
